<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>CLSU Performance Observatory - IRIS</title><link rel="stylesheet" href="{{ asset('assets/style.css') }}"><script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.0/chart.umd.min.js"></script></head><body><div class="topbar green"><div><h1>CLSU Performance Observatory</h1><span>RANKINGS DASHBOARD</span></div><div><span class="pill">Welcome, {{ auth()->user()->username }}</span>@if(auth()->user()->role==='admin')<a href="{{ route('admin.dashboard') }}" class="btn btn-ghost">Admin</a>@endif<form action="{{ route('logout') }}" method="POST" style="display:inline">@csrf<button type="submit" class="btn btn-ghost">Logout</button></form></div></div><div class="container"><h2>University-Wide Overview</h2><div class="card overview"><div><p class="label">BEST GLOBAL RANK</p><p class="big-number">{{ $best->global_rank ?? '—' }}</p><p class="sub">{{ $best->body_name ?? '' }} · {{ $best->year ?? '' }}</p></div><div><p class="label">PHILIPPINES RANK</p><p class="mid-number">{{ $phRank->ph_rank ?? '—' }}</p><p class="label">RANKING BODIES TRACKED</p><p class="mid-number">{{ (int)$bodyCount }}</p></div></div><h2>By Ranking Body</h2><div class="grid-3">@foreach($bodyCards as $row)<div class="card"><p class="label">{{ $row->short_name }}{{ $row->category ? ' · '.$row->category : '' }}</p><h3>{{ $row->name }}</h3><p class="big-number">{{ $row->global_rank ?? '—' }}</p><p class="sub">Global rank · {{ $row->year }}</p>@if($row->note)<p class="hint">{{ $row->note }}</p>@endif</div>@endforeach</div><h2>By College</h2><div class="grid-2"><div class="card"><h3>Global Rank Trend</h3><p class="sub">QS World University Rankings</p><canvas id="trendChart"></canvas></div><div class="card"><h3>College Contribution to Rank Score</h3><canvas id="collegeChart"></canvas></div></div><div class="card"><h3>AI Summary</h3><div id="ai-summary">Generating summary…</div><button onclick="loadSummary()" class="btn btn-outline btn-sm" style="margin-top:14px;">🔄 Regenerate</button></div><h2>National Program Rankings</h2><div class="card"><table><tr><th>Rank</th><th>Program</th><th>College</th><th>Score</th><th>Movement</th></tr>@foreach($programs as $row)@php $moveClass=$row->movement>0?'up':($row->movement<0?'down':'flat');$moveText=$row->movement>0?'+'.$row->movement:($row->movement<0?$row->movement:'—'); @endphp<tr><td>{{ (int)$row->national_rank }}</td><td>{{ $row->name }}</td><td>{{ $row->short_code }}</td><td>{{ number_format($row->score,1) }}</td><td class="{{ $moveClass }}">{{ $moveText }}</td></tr>@endforeach</table></div>@if(count($breakdownSections))<h2>Category Breakdowns</h2><p class="sub">Per-category detail underneath each body's headline rank — e.g. THE Impact's per-SDG ranks, WURI's award categories, or QS Stars' per-category ratings.</p><div class="grid-3">@foreach($breakdownSections as $idx=>$section)<div class="card"><p class="label">{{ $section['body']->short_name }} · {{ $section['body']->year }}</p><h3>{{ $section['items'][0]->group_label ?? 'Breakdown' }}</h3><canvas id="breakdownChart{{ $idx }}" height="220"></canvas><table style="margin-top:12px;">@foreach($section['items'] as $item)<tr><td>{{ $item->item_label }}</td><td style="text-align:right;">{{ $item->rank_display ?? '—' }}</td></tr>@endforeach</table></div>@endforeach</div>@endif @if(count($accreditations))<h2>Program Accreditation</h2><p class="sub">AUN-QA (and similar) program-level assessments — overall verdict plus the average of each program's numeric criterion scores.</p><div class="card"><table><tr><th>Program</th><th>Body</th><th>Year</th><th>Assessment Date</th><th>Avg. Criterion Score</th><th>Overall Verdict</th></tr>@foreach($accreditations as $row)<tr><td>{{ $row->program_name }}</td><td>{{ $row->accrediting_body }}</td><td>{{ $row->year }}</td><td>{{ $row->assessment_date ?? '—' }}</td><td>{{ $row->avg_score !== null ? number_format($row->avg_score,2) : '—' }}</td><td>{{ $row->verdict ?? '—' }}</td></tr>@endforeach</table></div>@endif</div><script>const trendYears=@json($trendYears),trendRanks=@json($trendRanks),trendDisplay=@json($trendDisplay),collegeLabels=@json($collegeLabels),collegeValues=@json($collegeValues);new Chart(document.getElementById('trendChart'),{type:'line',data:{labels:trendYears,datasets:[{label:'Global Rank',data:trendRanks,borderColor:'#1f7a3f',backgroundColor:'#1f7a3f',tension:.3,spanGaps:true}]},options:{scales:{y:{reverse:true,title:{display:true,text:'Lower = better'}}},plugins:{tooltip:{callbacks:{label:(ctx)=>'Rank: '+(trendDisplay[ctx.dataIndex]??'—')}}}}});new Chart(document.getElementById('collegeChart'),{type:'doughnut',data:{labels:collegeLabels,datasets:[{data:collegeValues,backgroundColor:['#1f7a3f','#0f4d24','#d4a017','#f2c14e','#b0b0b0','#8fbf9f']}]}});const breakdownSections=@json(array_map(fn($s)=>['labels'=>$s['items']->pluck('item_label')->values(),'values'=>$s['items']->map(fn($i)=>$i->rank_value!==null?(int)$i->rank_value:null)->values()],$breakdownSections));breakdownSections.forEach((section,idx)=>{const el=document.getElementById('breakdownChart'+idx);if(!el)return;new Chart(el,{type:'bar',data:{labels:section.labels,datasets:[{label:'Rank',data:section.values,backgroundColor:'#1f7a3f'}]},options:{indexAxis:'y',scales:{x:{reverse:true,title:{display:true,text:'Lower = better'}}},plugins:{legend:{display:false}}}})});function loadSummary(){document.getElementById('ai-summary').textContent='Generating summary…';fetch('{{ route('api.summary') }}').then(res=>res.json()).then(data=>document.getElementById('ai-summary').textContent=data.summary).catch(()=>document.getElementById('ai-summary').textContent='Summary unavailable right now.')}loadSummary();</script></body></html>
